(()=>{'use strict';const links=document.getElementById('links'),menu=document.getElementById('menu');menu.addEventListener('click',()=>{let isOpen=links.classList.toggle('open');menu.setAttribute('aria-expanded',String(isOpen));menu.textContent=isOpen?'×':'☰'});document.querySelectorAll('.links a').forEach(a=>a.addEventListener('click',()=>{links.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'}));const toast=document.getElementById('toast');let hideToast;function notify(t){toast.textContent=t;toast.classList.add('show');clearTimeout(hideToast);hideToast=setTimeout(()=>toast.classList.remove('show'),3800)}document.querySelectorAll('[data-cv]').forEach(b=>b.addEventListener('click',()=>notify('File CV asli belum ditambahkan. Tambahkan PDF Christin terlebih dahulu.')));const dialog=document.getElementById('detailDialog'),t=document.getElementById('detailTitle'),body=document.getElementById('detailText');document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>{const pkbi=b.dataset.detail==='pkbi';t.textContent=pkbi?'Internship at PKBI':'PLP di SMA Negeri 19 Palembang';body.textContent=pkbi?'Christin mengikuti kegiatan magang di Perkumpulan Keluarga Berencana Indonesia. Tugas, tahun, dan pencapaian akan dilengkapi setelah dikonfirmasi.':'Christin menjalani Pengenalan Lapangan Persekolahan dan praktik mengajar di SMA Negeri 19 Palembang. Rincian materi dan periodenya dapat dilengkapi sesuai pengalaman nyata.';dialog.showModal()}));document.getElementById('closeDialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});const navItems=[...document.querySelectorAll('.links a')];const sectionIds=['home','about','experience','education','skills','contact'];let ticking=false;function updateNav(){const current=sectionIds.filter(id=>{const e=document.getElementById(id);return e&&e.getBoundingClientRect().top<=150}).pop()||'home';navItems.forEach(a=>{const selected=a.getAttribute('href')==='#'+current;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{updateNav();ticking=false});ticking=true}},{passive:true});addEventListener('hashchange',updateNav);updateNav();document.getElementById('year').textContent=new Date().getFullYear();const els=document.querySelectorAll('[data-reveal]');if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});els.forEach(e=>observer.observe(e))}else els.forEach(e=>e.classList.add('visible'));})();

