(()=>{const gallery=document.getElementById('photoGallery'),modal=document.getElementById('detailDialog'),lightbox=document.getElementById('photoLightbox'),big=document.getElementById('lightboxImage');const data={pkbi:[],plp:[]};document.querySelectorAll('.exp-card').forEach((card,i)=>{const name=i===0?'pkbi':'plp',img=card.querySelector('.exp-cover img');data[name].push({src:img.src,alt:img.alt})});
// Galeri tambahan: gambar lainnya diisi oleh aset foto asli tertanam.
const extra=window.__christinPhotos||{};for(const key of Object.keys(extra))if(data[key])data[key].push(...extra[key]);
document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>{const photos=data[button.dataset.detail]||[];gallery.replaceChildren();photos.forEach((photo,index)=>{const figure=document.createElement('figure'),btn=document.createElement('button'),img=document.createElement('img'),caption=document.createElement('figcaption');btn.type='button';btn.setAttribute('aria-label','Perbesar foto '+(index+1));img.src=photo.src;img.alt=photo.alt;img.loading='lazy';btn.append(img);btn.addEventListener('click',()=>{big.src=photo.src;big.alt=photo.alt;lightbox.showModal()});caption.textContent=photo.alt;figure.append(btn,caption);gallery.append(figure)})}));
document.getElementById('closeLightbox').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});})();

